const { test } = require("node:test");
const assert = require("node:assert/strict");
const { startServer, api } = require("./helpers");

test("deactivated warehouse is excluded from list unless includeInactive", async () => {
  const { base, close } = startServer();
  try {
    const w = await api(base, "POST", "/api/warehouses", { name: "W", location: "x" });
    await api(base, "POST", `/api/warehouses/${w.json.id}/deactivate`, {});

    const list = await api(base, "GET", "/api/warehouses");
    assert.equal(list.json.length, 0);

    const withInactive = await api(base, "GET", "/api/warehouses?includeInactive=true");
    assert.equal(withInactive.json.length, 1);
    assert.equal(withInactive.json[0].active, false);
  } finally {
    await close();
  }
});

test("deactivated warehouse rejects new items and new movements, but keeps existing items readable", async () => {
  const { base, close } = startServer();
  try {
    const w = await api(base, "POST", "/api/warehouses", { name: "W", location: "x" });
    const item = await api(base, "POST", "/api/items", {
      sku: "A", name: "A", warehouseId: w.json.id, quantity: 5, reorderThreshold: 0,
    });
    assert.equal(item.status, 201);

    await api(base, "POST", `/api/warehouses/${w.json.id}/deactivate`, {});

    const rejectedItem = await api(base, "POST", "/api/items", {
      sku: "B", name: "B", warehouseId: w.json.id, quantity: 1, reorderThreshold: 0,
    });
    assert.equal(rejectedItem.status, 400);

    const rejectedMovement = await api(base, "POST", `/api/items/${item.json.id}/movements`, {
      type: "IN", quantity: 1,
    });
    assert.equal(rejectedMovement.status, 400, "movements against items in a deactivated warehouse must be blocked too");

    const stillReadable = await api(base, "GET", `/api/items/${item.json.id}`);
    assert.equal(stillReadable.status, 200);
    assert.equal(stillReadable.json.quantity, 5, "the blocked movement must not have changed quantity");
  } finally {
    await close();
  }
});

