let warehouses = new Map();
let nextId = 1;

function createWarehouse({ name, location }) {
  const warehouse = { id: nextId++, name, location, active: true };
  warehouses.set(warehouse.id, warehouse);
  return warehouse;
}

function getWarehouse(id) {
  return warehouses.get(id);
}

function listWarehouses({ includeInactive } = {}) {
  const all = [...warehouses.values()].sort((a, b) => a.id - b.id);
  return includeInactive ? all : all.filter((w) => w.active);
}

function deactivateWarehouse(id) {
  const warehouse = warehouses.get(id);
  if (!warehouse) return undefined;
  warehouse.active = false;
  return warehouse;
}

/** Test hook: wipe all state (each test file starts from an empty store). */
function resetStore() {
  warehouses = new Map();
  nextId = 1;
}

module.exports = {
  createWarehouse,
  getWarehouse,
  listWarehouses,
  deactivateWarehouse,
  resetStore,
};

